println("Sortiert?   " + Diagnose.istAufsteigendSortiert(schatz));
println("Schnitt:    " + Diagnose.durchschnitt(schatz));
println("Vokale:     " + Diagnose.anzahlVokale("Das Dungeon der Datenstrukturen"));
