        assertEquals(15, r.getVertauschungen(), "bubbleSort im schlechtesten Fall (n = 6): 15 Vertauschungen");
        assertEquals(15, r.getVergleiche(), "bubbleSort im schlechtesten Fall (n = 6): 5 + 4 + 3 + 2 + 1 = 15 Vergleiche - wird die innere Schleife in jedem Durchlauf um 1 kuerzer?");
    }

    @Test
    public void experte_bubbleSort_stabil() {
