        assertEquals(0, r.getVertauschungen(), "einfuegenSortiert schiebt Eintraege nach rechts (eintraege[i] = eintraege[i - 1]) - ohne vertausche(...)");
        assertTrue(r.getVergleiche() > 0, "einfuegenSortiert muss Eintraege ueber besser(...) vergleichen");
