        leer.insertionSort();
        leer.bubbleSort();
        assertEquals(0, leer.getVergleiche(), "Eine leere Liste sortieren: 0 Vergleiche und kein Absturz");
        String[] namen = {"Aria"};
        int[] punkte = {500};
        Rangliste eins = TestHilfe.liste(1, namen, punkte);
        eins.selectionSort();
        eins.insertionSort();
        eins.bubbleSort();
        assertEquals(0, eins.getVergleiche(), "Eine Liste mit einem Eintrag sortieren: 0 Vergleiche und kein Absturz");
        assertEquals("Aria", TestHilfe.namen(eins), "Der eine Eintrag bleibt erhalten");
    }

    @Test
    public void experte_volleListeUndEinfuegenGleichSortieren() {
        String[] namen = {"Aria", "Brann", "Cyra", "Dorn", "Elin"};
        int[] punkte = {1200, 800, 1500, 950, 600};
        Rangliste a = TestHilfe.liste(5, namen, punkte);
        Rangliste b = TestHilfe.liste(5, namen, punkte);
        Rangliste c = TestHilfe.liste(5, namen, punkte);
        a.selectionSort();
        b.insertionSort();
        c.bubbleSort();
        assertEquals("Cyra,Aria,Dorn,Brann,Elin", TestHilfe.namen(a), "selectionSort mit VOLLER Liste (Kapazitaet 5) - Index-Grenzen pruefen!");
        assertEquals("Cyra,Aria,Dorn,Brann,Elin", TestHilfe.namen(b), "insertionSort mit VOLLER Liste (Kapazitaet 5) - Index-Grenzen pruefen!");
        assertEquals("Cyra,Aria,Dorn,Brann,Elin", TestHilfe.namen(c), "bubbleSort mit VOLLER Liste (Kapazitaet 5) - Index-Grenzen pruefen!");
        Rangliste d = new Rangliste(5);
        for (int i = 0; i < namen.length; i++) {
            d.einfuegenSortiert(new Eintrag(namen[i], punkte[i], 100));
        }
        assertEquals("Cyra,Aria,Dorn,Brann,Elin", TestHilfe.namen(d), "Fuenfmal einfuegenSortiert in eine leere Liste ergibt ebenfalls die sortierte Rangliste");
    }
