// ================== Level 3.1 – Rekursion (DS 18) =====================

class L31RekursionTest {

    @Test
    public void basis_fakultaet() {
        assertEquals(120, Rekursion.fakultaet(5), "fakultaet(5) = 5 * 4 * 3 * 2 * 1 = 120");
        assertEquals(6, Rekursion.fakultaet(3), "fakultaet(3) = 3 * 2 * 1 = 6");
        assertEquals(1, Rekursion.fakultaet(1), "fakultaet(1) = 1");
        assertEquals(3628800, Rekursion.fakultaet(10), "fakultaet(10) = 3628800");
    }

    @Test
    public void basis_fakultaet_basisfallNull() {
        assertEquals(1, Rekursion.fakultaet(0), "fakultaet(0) = 1 (Basisfall n = 0). Bei StackOverflowError wird dein Basisfall bei n = 0 nie erreicht");
        assertEquals(2, Rekursion.fakultaet(2), "fakultaet(2) = 2 * fakultaet(1) = 2");
    }

    @Test
    public void basis_summeBis() {
        assertEquals(10, Rekursion.summeBis(4), "summeBis(4) = 0 + 1 + 2 + 3 + 4 = 10");
        assertEquals(55, Rekursion.summeBis(10), "summeBis(10) = 55");
        assertEquals(1, Rekursion.summeBis(1), "summeBis(1) = 0 + 1 = 1");
    }

    @Test
    public void basis_summeBis_basisfallNull() {
        assertEquals(3, Rekursion.summeBis(2), "summeBis(2) = 0 + 1 + 2 = 3");
        assertEquals(0, Rekursion.summeBis(0), "summeBis(0) = 0. Bei StackOverflowError fehlt der Basisfall n = 0 (n = 1 reicht nicht)");
    }

    @Test
    public void basis_potenz() {
        assertEquals(1024, Rekursion.potenz(2, 10), "potenz(2, 10) = 1024");
        assertEquals(81, Rekursion.potenz(3, 4), "potenz(3, 4) = 3 * 3 * 3 * 3 = 81");
        assertEquals(5, Rekursion.potenz(5, 1), "potenz(5, 1) = 5");
        assertEquals(-8, Rekursion.potenz(-2, 3), "potenz(-2, 3) = (-2) * (-2) * (-2) = -8");
    }

    @Test
    public void basis_potenz_exponentNull() {
        assertEquals(1, Rekursion.potenz(7, 0), "potenz(7, 0) = 1 (Basisfall exponent = 0). Bei StackOverflowError den Basisfall pruefen!");
        assertEquals(49, Rekursion.potenz(7, 2), "potenz(7, 2) = 49");
    }

    @Test
    public void erweiterung_anzahlZiffern() {
        assertEquals(4, Rekursion.anzahlZiffern(4711), "4711 hat 4 Ziffern");
        assertEquals(1, Rekursion.anzahlZiffern(7), "7 hat 1 Ziffer");
        assertEquals(2, Rekursion.anzahlZiffern(10), "10 hat 2 Ziffern");
        assertEquals(3, Rekursion.anzahlZiffern(100), "100 hat 3 Ziffern - auch die Nullen zaehlen");
    }

    @Test
    public void erweiterung_anzahlZiffern_null() {
        assertEquals(1, Rekursion.anzahlZiffern(0), "0 hat EINE Ziffer: anzahlZiffern(0) = 1 (Basisfall n < 10, nicht n == 0)");
        assertEquals(2, Rekursion.anzahlZiffern(99), "99 hat 2 Ziffern");
    }

    @Test
    public void erweiterung_istPalindrom() {
        assertTrue(Rekursion.istPalindrom("otto"), "'otto' ist ein Palindrom (gerade Laenge)");
        assertTrue(Rekursion.istPalindrom("level"), "'level' ist ein Palindrom (ungerade Laenge)");
        assertFalse(Rekursion.istPalindrom("abc"), "'abc' ist kein Palindrom");
        assertFalse(Rekursion.istPalindrom("abca"), "'abca': erstes und letztes Zeichen gleich, aber 'bc' in der Mitte ist kein Palindrom");
        assertFalse(Rekursion.istPalindrom("Otto"), "'Otto' ist kein Palindrom: 'O' und 'o' sind verschiedene Zeichen");
    }

    @Test
    public void erweiterung_istPalindrom_randfaelle() {
        assertTrue(Rekursion.istPalindrom(""), "Die leere Zeichenkette ist ein Palindrom (Basisfall)");
        assertTrue(Rekursion.istPalindrom("x"), "Ein einzelnes Zeichen ist ein Palindrom (Basisfall)");
        assertTrue(Rekursion.istPalindrom("aa"), "'aa' ist ein Palindrom");
        assertFalse(Rekursion.istPalindrom("ab"), "'ab' ist kein Palindrom");
        assertTrue(Rekursion.istPalindrom("abcba"), "'abcba' ist ein Palindrom - bei ungerader Laenge muss der Basisfall Laenge <= 1 greifen");
    }

    @Test
    public void erweiterung_summeAb() {
        int[] r = {3, 8, 2, 5};
        assertEquals(18, Rekursion.summeAb(r, 0), "summeAb({3, 8, 2, 5}, 0) = 3 + 8 + 2 + 5 = 18");
        assertEquals(7, Rekursion.summeAb(r, 2), "summeAb({3, 8, 2, 5}, 2) = 2 + 5 = 7");
        assertEquals(5, Rekursion.summeAb(r, 3), "summeAb({3, 8, 2, 5}, 3) = 5 (nur das letzte Element)");
    }

    @Test
    public void erweiterung_summeAb_basisfall() {
        int[] r = {3, 8, 2, 5};
        assertEquals(15, Rekursion.summeAb(r, 1), "summeAb({3, 8, 2, 5}, 1) = 8 + 2 + 5 = 15");
        assertEquals(0, Rekursion.summeAb(r, 4), "summeAb(r, r.length) = 0 - Basisfall i == r.length (keine Elemente mehr)");
        assertEquals(0, Rekursion.summeAb(new int[0], 0), "Leere Reihung: summeAb(r, 0) = 0 - Basisfall i == r.length");
        int[] neg = {-4, 4, -9};
        assertEquals(-9, Rekursion.summeAb(neg, 0), "summeAb({-4, 4, -9}, 0) = -9");
    }

    @Test
    public void experte_maximumAb() {
        int[] r = {4, 9, 2, 7, 1};
        assertEquals(9, Rekursion.maximumAb(r, 0), "maximumAb({4, 9, 2, 7, 1}, 0) = 9");
        assertEquals(7, Rekursion.maximumAb(r, 2), "maximumAb({4, 9, 2, 7, 1}, 2) = 7 - erst ab Index 2 suchen");
        assertEquals(1, Rekursion.maximumAb(r, 4), "maximumAb({4, 9, 2, 7, 1}, 4) = 1 (Basisfall: letztes Element)");
    }

    @Test
    public void experte_maximumAb_raender() {
        int[] vorne = {12, 3, 5};
        int[] hinten = {3, 5, 12};
        int[] neg = {-5, -2, -8};
        assertEquals(12, Rekursion.maximumAb(vorne, 0), "Maximum ganz vorne: {12, 3, 5} -> 12");
        assertEquals(12, Rekursion.maximumAb(hinten, 0), "Maximum ganz hinten: {3, 5, 12} -> 12");
        assertEquals(-2, Rekursion.maximumAb(neg, 0), "Nur negative Werte: {-5, -2, -8} -> -2 (nicht mit 0 starten!)");
        int[] eins = {6};
        assertEquals(6, Rekursion.maximumAb(eins, 0), "Ein Element: {6} -> 6");
    }

    @Test
    public void experte_dual() {
        assertEquals("110", Rekursion.dual(6), "dual(6) = '110' (6 = 4 + 2)");
        assertEquals("1101", Rekursion.dual(13), "dual(13) = '1101' (13 = 8 + 4 + 1)");
        assertEquals("1000", Rekursion.dual(8), "dual(8) = '1000'");
        assertEquals("1", Rekursion.dual(1), "dual(1) = '1'");
    }

    @Test
    public void experte_dual_basisfall() {
        assertEquals("10", Rekursion.dual(2), "dual(2) = '10' - ohne fuehrende Null (nicht '010')");
        assertEquals("0", Rekursion.dual(0), "dual(0) = '0' (nicht die leere Zeichenkette)");
        assertEquals("11111111", Rekursion.dual(255), "dual(255) = '11111111'");
    }

    @Test
    public void experte_fibonacci() {
        assertEquals(5, Rekursion.fibonacci(5), "fibonacci(5) = 5 (0, 1, 1, 2, 3, 5)");
        assertEquals(55, Rekursion.fibonacci(10), "fibonacci(10) = 55");
        assertEquals(1, Rekursion.fibonacci(2), "fibonacci(2) = fib(1) + fib(0) = 1");
        assertEquals(1, Rekursion.fibonacci(1), "fibonacci(1) = 1 (Basisfall)");
        assertEquals(0, Rekursion.fibonacci(0), "fibonacci(0) = 0 (Basisfall)");
    }

    @Test
    public void experte_fibonacci_aufrufe() {
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(5);
        assertEquals(15, Rekursion.aufrufe, "fibonacci(5) ruft sich (mit dem ersten Aufruf) 15-mal auf - zeichne den Aufrufbaum! aufrufe++ als ERSTE Anweisung, zwei Selbstaufrufe");
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(1);
        assertEquals(1, Rekursion.aufrufe, "fibonacci(1) ist ein Basisfall: genau 1 Aufruf");
        Rekursion.aufrufe = 0;
        Rekursion.fibonacci(10);
        assertEquals(177, Rekursion.aufrufe, "fibonacci(10) braucht 177 Aufrufe - baumrekursiv waechst die Zahl der Aufrufe sehr schnell");
    }
}


// ============ Level 3.2 – Die Dungeon-Karte (DS 19 und 20) ============

class L32KarteTest {

    @Test
    public void basis_istImFeld() {
        Karte k = Kartenbuch.hoehle();          // 5 Zeilen, 7 Spalten
        assertTrue(k.istImFeld(0, 0), "Hoehle: (0, 0) ist die Ecke oben links - im Feld");
        assertTrue(k.istImFeld(4, 6), "Hoehle (5 Zeilen, 7 Spalten): (4, 6) ist die Ecke unten rechts - im Feld. Zeilen und Spalten vertauscht?");
        assertTrue(k.istImFeld(2, 3), "Hoehle: (2, 3) liegt mitten im Feld");
        assertFalse(k.istImFeld(5, 0), "Hoehle: Zeile 5 gibt es nicht (Zeilen 0 bis 4)");
        assertFalse(k.istImFeld(0, 7), "Hoehle: Spalte 7 gibt es nicht (Spalten 0 bis 6)");
        assertFalse(k.istImFeld(-1, 3), "Hoehle: Zeile -1 gibt es nicht");
        assertFalse(k.istImFeld(2, -1), "Hoehle: Spalte -1 gibt es nicht");
    }

    @Test
    public void basis_istImFeld_lichtung() {
        Karte k = Kartenbuch.lichtung();        // 3 Zeilen, 4 Spalten
        assertTrue(k.istImFeld(2, 3), "Lichtung (3 Zeilen, 4 Spalten): (2, 3) ist im Feld");
        assertTrue(k.istImFeld(0, 3), "Lichtung: (0, 3) ist im Feld");
        assertFalse(k.istImFeld(3, 2), "Lichtung: Zeile 3 gibt es nicht - Zeilen: feld.length, Spalten: feld[0].length");
        assertFalse(k.istImFeld(2, 4), "Lichtung: Spalte 4 gibt es nicht");
    }

    @Test
    public void basis_istBegehbar() {
        Karte k = Kartenbuch.hoehle();
        assertTrue(k.istBegehbar(1, 2), "Hoehle: (1, 2) ist '.' - begehbar");
        assertTrue(k.istBegehbar(1, 1), "Hoehle: (1, 1) ist der Start 'S' - begehbar");
        assertTrue(k.istBegehbar(3, 5), "Hoehle: (3, 5) ist das Ziel 'Z' - begehbar");
        assertFalse(k.istBegehbar(0, 0), "Hoehle: (0, 0) ist eine Wand '#'");
        assertFalse(k.istBegehbar(2, 3), "Hoehle: (2, 3) ist eine Wand '#' mitten in der Hoehle");
    }

    @Test
    public void basis_istBegehbar_ausserhalb() {
        Karte k = Kartenbuch.lichtung();
        assertTrue(k.istBegehbar(0, 0), "Lichtung: (0, 0) ist '.' - begehbar");
        assertFalse(k.istBegehbar(-1, 0), "(-1, 0) liegt ausserhalb: false - und KEIN Absturz (zuerst istImFeld pruefen!)");
        assertFalse(k.istBegehbar(0, -1), "(0, -1) liegt ausserhalb: false");
        assertFalse(k.istBegehbar(3, 1), "(3, 1) liegt ausserhalb: false");
        assertFalse(k.istBegehbar(1, 4), "(1, 4) liegt ausserhalb: false");
    }

    @Test
    public void basis_istBegehbar_besucht() {
        String[] zeilen = {"S+*x.Z#"};
        Karte k = new Karte(zeilen);
        assertTrue(k.istBegehbar(0, 4), "'.' ist begehbar");
        assertTrue(k.istBegehbar(0, 0), "'S' ist begehbar");
        assertTrue(k.istBegehbar(0, 5), "'Z' ist begehbar");
        assertFalse(k.istBegehbar(0, 1), "'+' (schon gelueftet) ist NICHT begehbar");
        assertFalse(k.istBegehbar(0, 2), "'*' (schon auf dem Weg) ist NICHT begehbar");
        assertFalse(k.istBegehbar(0, 3), "'x' (Sackgasse) ist NICHT begehbar");
        assertFalse(k.istBegehbar(0, 6), "'#' (Wand) ist NICHT begehbar");
    }

    @Test
    public void basis_anzahlWaende() {
        assertEquals(21, Kartenbuch.hoehle().anzahlWaende(), "Die Hoehle hat 21 Waende");
        assertEquals(50, Kartenbuch.labyrinth().anzahlWaende(), "Das Labyrinth hat 50 Waende");
        assertEquals(31, Kartenbuch.kerker().anzahlWaende(), "Der Kerker hat 31 Waende - laufen beide Schleifen bis zum letzten Index?");
        assertEquals(2, Kartenbuch.lichtung().anzahlWaende(), "Die Lichtung hat 2 Waende");
    }

    @Test
    public void erweiterung_anzahlBegehbareNachbarn() {
        Karte k = Kartenbuch.hoehle();
        assertEquals(3, k.anzahlBegehbareNachbarn(2, 2), "Hoehle (2, 2): oben '.', rechts '#', unten '.', links '.' -> 3");
        assertEquals(2, k.anzahlBegehbareNachbarn(1, 1), "Hoehle (1, 1) = S: oben '#', rechts '.', unten '.', links '#' -> 2");
        assertEquals(3, k.anzahlBegehbareNachbarn(2, 5), "Hoehle (2, 5): oben '.', rechts '#', unten 'Z', links '.' -> 3 (Z zaehlt als begehbar)");
        assertEquals(1, k.anzahlBegehbareNachbarn(0, 1), "Hoehle (0, 1) ist eine Wand - gezaehlt werden trotzdem die Nachbarn: nur unten 'S' -> 1 (oben ist ausserhalb!)");
    }

    @Test
    public void erweiterung_anzahlBegehbareNachbarn_randUndDiagonal() {
        Karte k = Kartenbuch.lichtung();
        assertEquals(4, k.anzahlBegehbareNachbarn(1, 1), "Lichtung (1, 1) = S: alle vier Nachbarn sind '.' -> 4");
        assertEquals(2, k.anzahlBegehbareNachbarn(0, 0), "Lichtung (0, 0) ist die Ecke: oben und links liegen AUSSERHALB -> 2");
        assertEquals(2, k.anzahlBegehbareNachbarn(2, 3), "Lichtung (2, 3) = Z in der Ecke unten rechts -> 2");
        assertEquals(1, k.anzahlBegehbareNachbarn(0, 3), "Lichtung (0, 3): nur unten ist begehbar -> 1");
        assertEquals(3, k.anzahlBegehbareNachbarn(1, 2), "Lichtung (1, 2): oben '#', rechts '.', unten '.', links 'S' -> 3. Diagonale Felder zaehlen NICHT!");
    }

    @Test
    public void erweiterung_lueften_hoehle() {
        Karte k = Kartenbuch.hoehle();
        k.lueften(1, 1);
        String[] erwartet = {
            "#######",
            "#S++++#",
            "#++#++#",
            "#++++Z#",
            "#######"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Hoehle nach lueften(1, 1): alle '.' werden '+', S und Z bleiben sichtbar");
        assertEquals(12, k.anzahlGelueftet(), "Hoehle nach lueften(1, 1): 12 Felder sind gelueftet");
    }

    @Test
    public void erweiterung_lueften_labyrinth() {
        Karte k = Kartenbuch.labyrinth();
        k.lueften(1, 1);
        String[] erwartet = {
            "#########",
            "#S#+++#+#",
            "#+#+#+#+#",
            "#+++#+++#",
            "#+###+#+#",
            "#+++#+#Z#",
            "###+##.##",
            "#+++#...#",
            "#########"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Labyrinth nach lueften(1, 1): Die Kammer unten rechts bleibt vernebelt - sie ist nur UEBER ECK erreichbar (keine Diagonalen!)");
        assertEquals(25, k.anzahlGelueftet(), "Labyrinth nach lueften(1, 1): 25 Felder sind gelueftet");
    }

    @Test
    public void erweiterung_lueften_kerker() {
        Karte k = Kartenbuch.kerker();
        k.lueften(1, 1);
        String[] erwartet = {
            "########",
            "#S++#..#",
            "#+#+#Z.#",
            "#+++####",
            "#+#++++#",
            "########"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Kerker nach lueften(1, 1): Die Kammer mit dem Ziel bleibt vernebelt");
        Karte k2 = Kartenbuch.kerker();
        k2.lueften(2, 5);
        String[] erwartet2 = {
            "########",
            "#S..#++#",
            "#.#.#Z+#",
            "#...####",
            "#.#....#",
            "########"
        };
        assertEquals(Kartenbuch.text(erwartet2), k2.alsText(), "Kerker nach lueften(2, 5) - Start auf dem Ziel Z: nur die Zielkammer wird gelueftet, Z bleibt sichtbar");
        assertEquals(3, k2.anzahlGelueftet(), "Kerker nach lueften(2, 5): 3 Felder sind gelueftet");
    }

    @Test
    public void erweiterung_lueften_rand() {
        Karte k = Kartenbuch.lichtung();
        k.lueften(1, 1);
        String[] erwartet = {
            "++#+",
            "+S++",
            "#++Z"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Lichtung (ohne Randmauer) nach lueften(1, 1): alles wird gelueftet. Bei Absturz fehlt die Pruefung, ob (z, s) im Feld liegt");
        assertEquals(8, k.anzahlGelueftet(), "Lichtung nach lueften(1, 1): 8 Felder sind gelueftet");
    }

    @Test
    public void erweiterung_lueften_wandUndAusserhalb() {
        Karte k = Kartenbuch.hoehle();
        k.lueften(0, 0);
        k.lueften(2, 3);
        k.lueften(-1, 2);
        k.lueften(1, 7);
        String[] unveraendert = {
            "#######",
            "#S....#",
            "#..#..#",
            "#....Z#",
            "#######"
        };
        assertEquals(Kartenbuch.text(unveraendert), k.alsText(), "lueften auf einer Wand oder ausserhalb der Karte darf NICHTS veraendern (Basisfall)");
        k.lueften(2, 4);
        assertEquals(12, k.anzahlGelueftet(), "Hoehle nach lueften(2, 4): von jedem Gang aus wird die ganze Hoehle gelueftet - 12 Felder");
