        assertTrue(k.getFeld(3, 5) == 'Z', "Hoehle nach lueften(2, 4): Das Ziel bleibt 'Z'");
    }

    @Test
    public void erweiterung_anzahlGelueftet() {
        String[] zeilen = {"#++.", "+..+"};
        Karte k = new Karte(zeilen);
        assertEquals(4, k.anzahlGelueftet(), "Karte {'#++.', '+..+'}: 4 Felder sind '+' - auch das letzte Feld zaehlen!");
