    @Test
    public void experte_findeWeg_hoehle() {
        Karte k = Kartenbuch.hoehle();
        assertTrue(k.findeWeg(1, 1), "Hoehle: Es gibt einen Weg von S zu Z");
        String[] erwartet = {
            "#######",
            "#S****#",
            "#..#.*#",
            "#....Z#",
            "#######"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Hoehle nach findeWeg(1, 1): Weg mit '*' (Reihenfolge oben, rechts, unten, links!), nie besuchte Felder bleiben '.'");
