        assertTrue(k.findeWeg(1, 1), "Labyrinth: Es gibt einen Weg von S zu Z");
        String[] erwartet = {
            "#########",
            "#S#***#x#",
            "#*#*#*#x#",
            "#***#***#",
            "#.###.#*#",
            "#...#.#Z#",
            "###.##.##",
            "#...#...#",
            "#########"
        };
        assertEquals(Kartenbuch.text(erwartet), k.alsText(), "Labyrinth nach findeWeg(1, 1): Weg '*', Sackgasse oben rechts 'x' (Schritt zurueckgenommen!), Rest '.'");
