class Fraktal {

    // Zaehler - werden von der Werkstatt vor jedem Bild auf 0 gesetzt.
    static int aufrufe = 0;
    static int striche = 0;

    // Laeuft die angegebene Strecke rueckwaerts zurueck, ohne zu zeichnen.
    // Die zweite Drehung ist -180, damit sich beide exakt aufheben und
    // der Blickwinkel unveraendert bleibt.
    static void zurueck(Turtle t, double laenge) {
        t.penUp();
        t.turn(180);
        t.forward(laenge);
        t.turn(-180);
        t.penDown();
    }


    // ---------------- Deko 1: Baum (fertiges Beispiel) ----------------
    //
    // Basisfall:         tiefe 0 -> es wird nichts mehr gezeichnet
    // Rekursionsschritt: Stamm zeichnen, links und rechts je einen
    //                    kleineren Baum ansetzen, dann zurueckgehen
    //
    // Wichtig: Am Ende steht die Turtle wieder am Astansatz und blickt in
    // dieselbe Richtung wie vorher (+30 - 60 + 30 = 0). Nur deshalb kann
    // der Aufrufer danach einfach weiterzeichnen.

    static void baum(Turtle t, double laenge, int tiefe) {
        aufrufe++;
        if (tiefe == 0) {
            return;                            // Basisfall
        }

        t.forward(laenge);                     // Stamm zeichnen
        striche++;

        t.turn(30);                            // nach links drehen
        baum(t, laenge * 0.7, tiefe - 1);      // linker Teilbaum
        t.turn(-60);                           // nach rechts drehen
        baum(t, laenge * 0.7, tiefe - 1);      // rechter Teilbaum
        t.turn(30);                            // Blickrichtung zurueck

        zurueck(t, laenge);                    // zum Astansatz zurueck
    }


