    // links (+30), geradeaus, rechts (-30). Die Teilbaeume sind wieder
    // laenge * 0.7 lang. Am Ende muss die Blickrichtung wieder stimmen!

    static void baum3(Turtle t, double laenge, int tiefe) {
        aufrufe++;
        if (tiefe == 0) {
            return;
        }

