    // true, wenn der kuerzeste Weg von S nach Z auf der Rennkarte (Text)
    // in der gerade erzeugten Karte komplett frei ist (Breitensuche auf
    // der Rennkarte, dann den Weg rueckwaerts gegen die Karte pruefen).
    private static boolean wegOffen(String[] rk) {
        int zz = rk.length;
        int ss = rk[0].length();
        int[] vorgaenger = new int[zz * ss];
        boolean[] besucht = new boolean[zz * ss];
        int[] q = new int[zz * ss];
        int kopf = 0;
        int ende = 0;
        int ziel = -1;
        for (int z = 0; z < zz; z++) {
            for (int s = 0; s < ss; s++) {
                if (rk[z].charAt(s) == 'S') {
                    q[ende] = z * ss + s;
                    ende++;
                    besucht[z * ss + s] = true;
                    vorgaenger[z * ss + s] = -1;
                }
                if (rk[z].charAt(s) == 'Z') {
                    ziel = z * ss + s;
                }
            }
        }
        int[] dz = {-1, 0, 1, 0};
        int[] ds = {0, 1, 0, -1};
        while (kopf < ende) {
            int z = q[kopf] / ss;
            int s = q[kopf] % ss;
            kopf++;
            for (int r = 0; r < 4; r++) {
                int nz = z + dz[r];
                int ns = s + ds[r];
                if (nz >= 0 && nz < zz && ns >= 0 && ns < ss && !besucht[nz * ss + ns]
                        && rk[nz].charAt(ns) != '#') {
                    besucht[nz * ss + ns] = true;
                    vorgaenger[nz * ss + ns] = z * ss + s;
                    q[ende] = nz * ss + ns;
                    ende++;
                }
            }
        }
        int k = ziel;
        while (k != -1) {
            if (karte[k / ss][k % ss] == '#') {
                return false;
            }
            k = vorgaenger[k];
        }
        return true;
    }

    // Erzeugt ein Labyrinth mit zz Zeilen und ss Spalten (beide ungerade):
    // Tiefensuche mit eigenem Stapel, dazu einige zusaetzliche
    // Durchbrueche, damit es mehrere Wege gibt. S kommt nach (sz, sp),
    // Z nach (zz2, zp); sz bzw. zz2 = -1 heisst: zufaellige Zeile.
    private static void erzeugeLabyrinth(int startwert, int zz, int ss, int sz, int sp, int zz2, int zp) {
        saat = startwert;
        karte = new char[zz][ss];
        for (int z = 0; z < zz; z++) {
            for (int s = 0; s < ss; s++) {
                karte[z][s] = '#';
            }
        }
        int[] stapelZ = new int[zz * ss];
        int[] stapelS = new int[zz * ss];
        int oben = 0;
        karte[1][1] = '.';
        stapelZ[oben] = 1;
        stapelS[oben] = 1;
        oben++;
        int[] dz = {-1, 0, 1, 0};
        int[] ds = {0, 1, 0, -1};
        int[] moeglich = new int[4];
        while (oben > 0) {
            int z = stapelZ[oben - 1];
            int s = stapelS[oben - 1];
            int anzahl = 0;
            for (int r = 0; r < 4; r++) {
                int nz = z + 2 * dz[r];
                int ns = s + 2 * ds[r];
                if (nz > 0 && nz < zz - 1 && ns > 0 && ns < ss - 1 && karte[nz][ns] == '#') {
                    moeglich[anzahl] = r;
                    anzahl++;
                }
            }
            if (anzahl == 0) {
                oben--;
            } else {
                int r = moeglich[zufall(anzahl)];
                karte[z + dz[r]][s + ds[r]] = '.';
                karte[z + 2 * dz[r]][s + 2 * ds[r]] = '.';
                stapelZ[oben] = z + 2 * dz[r];
                stapelS[oben] = s + 2 * ds[r];
                oben++;
            }
        }
        // zusaetzliche Durchbrueche (nur Waende zwischen zwei freien Feldern,
        // keine Eckpfeiler)
        int durchbrueche = 0;
        int versuche = 0;
        int ziel = (zz * ss) / 30;
        while (durchbrueche < ziel && versuche < 1000) {
            versuche++;
            int z = 1 + zufall(zz - 2);
            int s = 1 + zufall(ss - 2);
            if (karte[z][s] == '#' && (z + s) % 2 == 1) {
                boolean waagerecht = karte[z][s - 1] == '.' && karte[z][s + 1] == '.';
                boolean senkrecht = karte[z - 1][s] == '.' && karte[z + 1][s] == '.';
                if (waagerecht || senkrecht) {
                    karte[z][s] = '.';
                    durchbrueche++;
                }
            }
        }
        int zeileS = sz;
        if (zeileS < 0) {
            zeileS = 1 + 2 * zufall((zz - 1) / 2);
        }
        int zeileZ = zz2;
        if (zeileZ < 0) {
            zeileZ = 1 + 2 * zufall((zz - 1) / 2);
        }
        karte[zeileS][sp] = 'S';
        karte[zeileZ][zp] = 'Z';
    }

    private static void grafikVorbereiten() {
        if (!grafikBereit) {
            new World(900, 780);
            titel = new Text(20, 15, 30, "");
            titel.setFillColor("#DAA520");
            info = new Text(20, 690, 26, "");
            info.setFillColor("#8FA8C8");
            legende = new Text(20, 735, 20, "Wand dunkel | Nebel grau | gelueftet hell | Weg gold | Sackgasse rot | S blau | Z gruen");
            legende.setFillColor("#8C8C8C");
            grafikBereit = true;
        }
    }

    private static void faerbe(int z, int s) {
        String f = FARBE_NEBEL;
        if (karte[z][s] == '#') {
            f = FARBE_WAND;
        } else if (karte[z][s] == 'S') {
            f = FARBE_START;
        } else if (karte[z][s] == 'Z') {
            f = FARBE_ZIEL;
        } else if (zustand[z][s] == GELUEFTET) {
            f = FARBE_HELL;
        } else if (zustand[z][s] == WEG) {
            f = FARBE_WEG;
        } else if (zustand[z][s] == SACKGASSE) {
            f = FARBE_SACKGASSE;
        }
        kachel[z][s].setFillColor(f);
    }

    private static void zeigeStand() {
        if (modus == NEBEL_LUEFTEN) {
            info.setText("Gelueftet: " + fackeln);
        } else {
            info.setText("Schritte: " + schritte);
        }
    }
